using ReeLib;using System.Text.Json;using System.Collections;
Directory.SetCurrentDirectory("E:/CodexPepo/RE_Research");ResourceRepository.LocalResourceRepositoryFolder="E:/CodexPepo/RE_Research/references/reelib-cache";ResourceRepository.DisableOnlineUpdater=true;var parser=new RszParser("references/rszre9.json");parser.ReadPatch("references/rszre9_patch.json");var option=new RszFileOption(GameName.re9,parser);
object? Val(object? x,int depth=0){if(x is null)return null;if(x is RszInstance i){if(depth>0)return new{Ref=i.Index,Class=i.RszClass.name};var fields=new Dictionary<string,object?>();for(int k=0;k<i.Values.Length;k++)fields[i.Fields[k].name]=Val(i.Values[k],depth+1);return new{Index=i.Index,Class=i.RszClass.name,Userdata=i.RSZUserData?.Path,Fields=fields};}if(x is string||x.GetType().IsPrimitive||x is decimal)return x;if(x is IEnumerable a)return a.Cast<object?>().Select(v=>Val(v,depth)).ToArray();return x.ToString();}
var files=Directory.GetFiles("reports/3c/camera/samples","*.user.3",SearchOption.AllDirectories).Select(f=>new{File=f,Path=f.Replace('\\','/').Split("/natives/")[1],Rank=f.Contains("patch_004")?4:0}).GroupBy(f=>f.Path).Select(g=>g.OrderByDescending(f=>f.Rank).First()).ToArray();var log=new List<object>();foreach(var e in files){try{using var f=new UserFile(option,new FileHandler(e.File));if(!f.Read())throw new Exception("Read failed");var dest="reports/3c/camera/parsed/"+e.Path+".json";Directory.CreateDirectory(Path.GetDirectoryName(dest)!);File.WriteAllText(dest,JsonSerializer.Serialize(new{e.Path,e.File,Objects=f.RSZ.ObjectList.Select(x=>Val(x)),Instances=f.RSZ.InstanceList.Select(x=>Val(x))},new JsonSerializerOptions{WriteIndented=true}));log.Add(new{e.Path,e.File,Success=true});}catch(Exception ex){log.Add(new{e.Path,Success=false,Error=ex.Message});}}File.WriteAllText("reports/3c/camera/parse_log.json",JsonSerializer.Serialize(log));Console.WriteLine($"Parsed {log.Count} effective resources");
